import json, sys

def q(task, topics, prompt, options, correct, why, wrong, tips):
    multi = len(correct) > 1
    if multi:
        head = "### ✅ Why Options " + " & ".join(correct) + " are Correct"
    else:
        head = "### ✅ Why Option " + correct[0] + " is Correct"
    assert set(wrong.keys()) | set(correct) == set(options.keys()), (prompt[:40], wrong.keys())
    assert not (set(wrong.keys()) & set(correct))
    lines = [head, ""]
    lines += ["* **%s:** %s" % (k, v) for k, v in why]
    lines += ["", "---", "", "### ❌ Why Other Options Are Incorrect", ""]
    lines += ["* **Option %s is incorrect:** %s" % (k, wrong[k]) for k in sorted(wrong)]
    lines += ["", "---", "", "### 💡 SAA-C03 Exam Concept & AWS Best Practice", ""]
    lines += ["%d. **%s:** %s" % (i + 1, k, v) for i, (k, v) in enumerate(tips)]
    return {
        "domain": 3, "task": task, "topics": topics, "prompt": prompt,
        "options": options, "isMulti": multi, "requiredCount": len(correct),
        "correctAnswers": correct, "explanation": "\n".join(lines),
    }

