set1.append(q("3.1", ["Amazon S3", "S3 Transfer Acceleration", "S3 multipart upload"],
 "A media company stores user-submitted video files in an Amazon S3 bucket in the us-east-1 Region. Users in Asia and Europe upload files that are 2-8 GB in size and report that uploads are slow and often fail partway through, forcing them to restart from the beginning. The company wants to improve upload speed and reliability without deploying additional infrastructure in other Regions. Which combination of actions should a solutions architect take? (Select TWO.)",
 {"A": "Change the default storage class of uploaded objects to S3 Intelligent-Tiering.",
  "B": "Enable S3 Transfer Acceleration on the bucket and have clients use the accelerate endpoint.",
  "C": "Spread the uploaded objects across a larger number of key prefixes in the bucket.",
  "D": "Configure S3 Cross-Region Replication to replicate objects to buckets in Regions closer to the users.",
  "E": "Update the client application to use S3 multipart upload and upload parts in parallel."},
 ["B", "E"],
 [("Transfer Acceleration", "Routes uploads through the nearest CloudFront edge location and then over the optimized AWS backbone network to the bucket, which significantly improves long-distance transfer speed without deploying regional infrastructure."),
  ("Multipart upload", "Splits large objects into parts that can be uploaded in parallel to increase throughput. If a part fails, only that part is retried instead of the entire file, which improves reliability. AWS recommends multipart upload for objects larger than 100 MB."),
  ("Combined effect", "Together they address both the latency of long-distance uploads and the restart-from-scratch failure behavior.")],
 {"A": "Storage classes affect storage cost and retrieval characteristics. Intelligent-Tiering does not change upload speed or reliability.",
  "C": "S3 supports at least 3,500 PUT requests per second per prefix. Adding prefixes helps with very high request rates, not with the speed of individual large uploads over long distances.",
  "D": "Cross-Region Replication copies objects after they have been written to the source bucket. It does not make the initial upload from Asia or Europe to us-east-1 any faster, and it effectively deploys buckets in other Regions."},
 [("Long-distance uploads to a single bucket", "S3 Transfer Acceleration."),
  ("Large files / unreliable networks", "Multipart upload with parallel parts; retry only failed parts."),
  ("Prefixes", "Prefix design matters for request-rate scaling, not single-object throughput.")]))

