set1.append(q("3.2", ["Amazon EC2 Auto Scaling", "Amazon SQS", "Amazon CloudWatch"],
 "A company runs an image-processing application on Amazon EC2 instances in an Auto Scaling group. The instances poll an Amazon SQS standard queue for jobs. Job arrival is highly variable, and each instance can process about 20 messages per minute regardless of CPU usage. The company wants the group to scale so that the queue backlog is processed within an acceptable time while minimizing idle instances. Which scaling approach should a solutions architect recommend?",
 {"A": "Create a target tracking scaling policy that keeps average CPU utilization of the group at 50%.",
  "B": "Create scheduled scaling actions that add instances during business hours and remove them at night.",
  "C": "Publish a custom CloudWatch metric for backlog per instance (ApproximateNumberOfMessagesVisible divided by the number of InService instances) and create a target tracking policy on that metric.",
  "D": "Create a simple scaling policy that adds one instance whenever the NumberOfMessagesSent metric for the queue exceeds 100."},
 ["C"],
 [("Scale on the real unit of work", "Because throughput is bounded by messages processed per instance, not CPU, the backlog per instance metric directly reflects whether capacity matches demand."),
  ("Target tracking", "Setting the target to the acceptable backlog per instance (acceptable latency x processing rate) lets Auto Scaling add or remove instances proportionally and continuously, minimizing idle capacity. This is the pattern documented by AWS for SQS-based scaling."),
  ("Handles variability", "The policy reacts to actual queue depth rather than to fixed schedules or single thresholds.")],
 {"A": "CPU utilization is a poor proxy here because the processing rate is not CPU-bound. The queue could grow while CPU stays below the target, so the group would not scale out.",
  "B": "Job arrival is highly variable, not predictable by time of day. Scheduled scaling would either leave a backlog or run idle instances.",
  "D": "NumberOfMessagesSent measures arrivals, not the outstanding backlog relative to capacity. A simple scaling policy with a fixed step and cooldown reacts slowly and does not scale in proportionally."},
 [("SQS consumers on EC2", "Scale on backlog per instance with target tracking."),
  ("Choose the metric that represents the bottleneck", "CPU for CPU-bound fleets, request count per target for ALB-fronted fleets, queue backlog for worker fleets."),
  ("Predictable patterns", "Use scheduled or predictive scaling only when load follows a known pattern.")]))

