set1.append(q("3.3", ["Amazon RDS Proxy", "AWS Lambda", "Amazon RDS for PostgreSQL"],
 "A company's API is implemented with AWS Lambda functions that query an Amazon RDS for PostgreSQL DB instance. During traffic spikes, thousands of concurrent function invocations open new database connections, and the database reports 'too many connections' errors and high CPU usage from connection handling. The company must handle the spikes without throttling user requests and without rewriting the data access layer. What should a solutions architect do?",
 {"A": "Create a read replica of the DB instance and send half of the Lambda invocations to the replica.",
  "B": "Set reserved concurrency on the Lambda functions to a value lower than the database max_connections setting.",
  "C": "Create an Amazon RDS Proxy for the DB instance and configure the Lambda functions to connect through the proxy endpoint.",
  "D": "Migrate the DB instance to a larger instance class to increase the max_connections setting."},
 ["C"],
 [("Connection pooling", "RDS Proxy maintains a pool of database connections and multiplexes many client connections onto fewer database connections, which prevents connection exhaustion during Lambda bursts."),
  ("Minimal change", "The functions only change their connection endpoint; the SQL and data access layer stay the same. RDS Proxy can also use Secrets Manager and IAM authentication."),
  ("Resilience", "RDS Proxy reduces failover time and queues or limits connections gracefully instead of overwhelming the database.")],
 {"A": "A read replica helps read scaling but does not solve the connection storm, and write queries cannot be sent to a replica. It also requires routing logic in the application.",
  "B": "Reserved concurrency would cap concurrent executions, causing invocations above the limit to be throttled, which violates the requirement.",
  "D": "A larger instance raises the connection ceiling and cost, but each Lambda burst can still exceed it, and the overhead of opening and closing connections remains."},
 [("Lambda + relational database + too many connections", "Amazon RDS Proxy."),
  ("RDS Proxy features", "Connection pooling, faster failover, IAM authentication, and Secrets Manager integration.")]))

